let datos = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
let temperatura = Number(datos.temperatura).toFixed(2);
temperatura = Number(temperatura);
let umbral = 30;

// Recuperamos las variables de la memoria del nodo (o las iniciamos si no existen)
let estadoAlerta = context.get("estadoAlerta") || false;
let maxTempAlcanzada = context.get("maxTempAlcanzada") || 0;

let timestamp = new Date().toLocaleString("es-CL", {
    timeZone: "America/Santiago",
});

let texto = "";

// 1. CONDICIÓN: Supera el umbral por primera vez
if (temperatura > umbral && !estadoAlerta) {
    context.set("estadoAlerta", true);
    context.set("maxTempAlcanzada", temperatura);

    texto = `🚨 Alerta SmartHome IoT\n\nEvento: Temperatura ALTA superó umbral\nValor: ${temperatura} °C\nHora: ${timestamp}`;

// 2. CONDICIÓN: Ya estaba en alerta, pero subió mucho más (ej: subió 2 grados más)
} else if (temperatura > umbral && estadoAlerta) {
    if (temperatura >= maxTempAlcanzada + 2) {
        context.set("maxTempAlcanzada", temperatura); // Actualizamos el nuevo máximo
        texto = `📈 Alerta SmartHome IoT\n\nEvento: Temperatura SIGUE SUBIENDO\nValor: ${temperatura} °C\nHora: ${timestamp}`;
    } else {
        // Sigue alto, pero no ha subido lo suficiente para otra alerta. Ignoramos.
        return null; 
    }

// 3. CONDICIÓN: Bajó del umbral y se normalizó
} else if (temperatura <= umbral && estadoAlerta) {
    context.set("estadoAlerta", false);
    context.set("maxTempAlcanzada", 0); // Reseteamos la memoria

    texto = `✅ Alerta SmartHome IoT\n\nEvento: Temperatura NORMALIZADA\nValor: ${temperatura} °C\nHora: ${timestamp}`;

// 4. CONDICIÓN: Todo está normal, no hacemos nada
} else {
    return null;
}

