// PREPARACIÓN DE MENSAJES
// =======================
let telegramMsg = {
    payload: {
        chatId: -1003932861041,
        type: "message",
        content: texto
    }
};

let dashboardMsg = {
    payload: texto
};

// NOTA: Para que salgan ambos mensajes por una sola salida en Node-RED, 
// deben ir envueltos en un array extra.
return [[telegramMsg, dashboardMsg]];

